def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my_last, opp_last = history[-1]

    opp_d = 0
    my_d = 0
    for m, o in history:
        if o == 'D':
            opp_d += 1
        if m == 'D':
            my_d += 1

    recent_n = 10 if n >= 10 else n
    recent = history[-recent_n:]
    recent_opp_d = 0
    recent_my_d = 0
    for m, o in recent:
        if o == 'D':
            recent_opp_d += 1
        if m == 'D':
            recent_my_d += 1

    opp_streak = 0
    for m, o in reversed(history):
        if o == 'D':
            opp_streak += 1
        else:
            break

    my_streak = 0
    for m, o in reversed(history):
        if m == 'D':
            my_streak += 1
        else:
            break

    punish_total = 0
    forgive_total = 0
    punish_recent = 0
    forgive_recent = 0
    recent_start = max(1, n - 10)
    for i in range(1, n):
        if history[i-1][0] == 'D':
            if history[i][1] == 'D':
                punish_total += 1
                if i >= recent_start:
                    punish_recent += 1
            else:
                forgive_total += 1
                if i >= recent_start:
                    forgive_recent += 1

    if opp_d == 0:
        if my_d == 0:
            if 8 <= n <= 95:
                return 'D'
            return 'C'
        if forgive_total > 0 and punish_total == 0:
            return 'D'
        return 'C'

    if ((opp_d * 100 >= n * 60 and opp_d > my_d) or
            (recent_opp_d * 100 >= recent_n * 60 and opp_d > my_d + 1) or
            opp_streak >= 5):
        return 'D'

    if n >= 95:
        if opp_last == 'D':
            if opp_streak >= 3 and opp_d > my_d:
                return 'D'
            if opp_d <= my_d + 2:
                return 'C'
            return 'D'
        if my_last == 'D':
            return 'C'
        return 'C'

    if opp_last == 'D':
        if n >= 2 and history[-2][0] == 'D':
            if opp_streak >= 4 or recent_opp_d >= 5 or opp_d > my_d + 2:
                return 'D'
            return 'C'
        if opp_streak >= 2 or recent_opp_d >= 3 or opp_d > my_d + 1:
            return 'D'
        return 'D'

    if my_last == 'D':
        return 'C'

    if (30 <= n <= 90 and recent_opp_d == 0 and punish_total == 0 and
            opp_d <= 3 and my_d <= opp_d + 1 and n % 13 == 4):
        return 'D'

    return 'C'
